use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use serde::{Deserialize, Serialize};
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use ring::signature::{self, UnparsedPublicKey, ED25519};
use ring::hmac;

#[derive(Clone, Debug)]
pub struct ConnectionPool {
    connections: Arc<Mutex<Vec<DeviceConnection>>>,
    max_size: usize,
}

#[derive(Clone, Debug)]
pub struct DeviceConnection {
    pub device_id: String,
    pub authenticated: bool,
    pub permissions: Vec<String>,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct JwtHeader {
    pub alg: String,
    pub typ: String,
}

#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct JwtClaims {
    pub sub: String,
    pub device_id: String,
    pub permissions: Vec<String>,
    pub exp: u64,
}

pub struct FirmwareAuthService {
    pool: ConnectionPool,
    public_key: Vec<u8>,
    trusted_algorithms: Vec<String>,
}

impl FirmwareAuthService {
    pub fn new(public_key: Vec<u8>, pool_size: usize) -> Self {
        FirmwareAuthService {
            pool: ConnectionPool {
                connections: Arc::new(Mutex::new(Vec::with_capacity(pool_size))),
                max_size: pool_size,
            },
            public_key,
            trusted_algorithms: vec!["EdDSA".to_string()],
        }
    }

    fn decode_jwt_parts(&self, token: &str) -> Result<(JwtHeader, JwtClaims, Vec<u8>), String> {
        let parts: Vec<&str> = token.split('.').collect();
        if parts.len() != 3 {
            return Err("Invalid JWT structure".to_string());
        }

        let header_bytes = URL_SAFE_NO_PAD.decode(parts[0])
            .map_err(|e| format!("Header decode error: {}", e))?;
        let claims_bytes = URL_SAFE_NO_PAD.decode(parts[1])
            .map_err(|e| format!("Claims decode error: {}", e))?;
        let signature = URL_SAFE_NO_PAD.decode(parts[2])
            .map_err(|e| format!("Signature decode error: {}", e))?;

        let header: JwtHeader = serde_json::from_slice(&header_bytes)
            .map_err(|e| format!("Header parse error: {}", e))?;
        let claims: JwtClaims = serde_json::from_slice(&claims_bytes)
            .map_err(|e| format!("Claims parse error: {}", e))?;

        Ok((header, claims, signature))
    }

    fn is_algorithm_permitted(&self, alg: &str) -> bool {
        // Strictly enforce only algorithms in our trusted list
        let normalized = alg.to_uppercase();
        self.trusted_algorithms.iter().any(|a| a.to_uppercase() == normalized)
    }

    fn verify_signature(&self, token: &str, header: &JwtHeader, signature: &[u8]) -> Result<bool, String> {
        let message = token.rsplitn(2, '.').nth(1)
            .ok_or_else(|| "Cannot extract signed portion".to_string())?;

        match header.alg.as_str() {
            "EdDSA" => {
                let public_key = UnparsedPublicKey::new(&ED25519, &self.public_key);
                match public_key.verify(message.as_bytes(), signature) {
                    Ok(()) => Ok(true),
                    Err(_) => Ok(false),
                }
            }
            _ => Err(format!("Unsupported algorithm: {}", header.alg)),
        }
    }

    pub fn authenticate_device(&self, token: &str) -> Result<DeviceConnection, String> {
        let (header, claims, signature) = self.decode_jwt_parts(token)?;

        if !self.is_algorithm_permitted(&header.alg) {
            return Err(format!("Algorithm '{}' is not permitted", header.alg));
        }

        let valid = self.verify_signature(token, &header, &signature)?;
        if !valid {
            return Err("Signature verification failed".to_string());
        }

        let now = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map_err(|e| format!("Time error: {}", e))?
            .as_secs();

        if claims.exp < now {
            return Err("Token expired".to_string());
        }

        let conn = DeviceConnection {
            device_id: claims.device_id.clone(),
            authenticated: true,
            permissions: claims.permissions.clone(),
        };

        self.add_to_pool(conn.clone())?;
        Ok(conn)
    }

    fn add_to_pool(&self, conn: DeviceConnection) -> Result<(), String> {
        let mut pool = self.pool.connections.lock()
            .map_err(|_| "Pool lock poisoned".to_string())?;

        if pool.len() >= self.pool.max_size {
            // Evict oldest connection
            pool.remove(0);
        }
        pool.push(conn);
        Ok(())
    }

    pub fn get_active_connections(&self) -> Result<Vec<DeviceConnection>, String> {
        let pool = self.pool.connections.lock()
            .map_err(|_| "Pool lock poisoned".to_string())?;
        Ok(pool.clone())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_rejects_none_algorithm() {
        let service = FirmwareAuthService::new(vec![0u8; 32], 10);
        let header = JwtHeader { alg: "none".to_string(), typ: "JWT".to_string() };
        assert!(!service.is_algorithm_permitted(&header.alg));
    }

    #[test]
    fn test_rejects_hmac_algorithm() {
        let service = FirmwareAuthService::new(vec![0u8; 32], 10);
        let header = JwtHeader { alg: "HS256".to_string(), typ: "JWT".to_string() };
        assert!(!service.is_algorithm_permitted(&header.alg));
    }
}
